import json

n = 2017

def is_prime(m):
    if m < 2:
        return False
    d = 2
    while d * d <= m:
        if m % d == 0:
            return False
        d += 1
    return True

def prime_factors(m):
    fs = []
    d = 2
    while d * d <= m:
        if m % d == 0:
            fs.append(d)
            while m % d == 0:
                m //= d
        d += 1
    if m > 1:
        fs.append(m)
    return fs

def order_mod(g, m, limit):
    # exhaustive: multiplicative order of g modulo m, searched up to limit
    x = 1
    for k in range(1, limit + 1):
        x = (x * g) % m
        if x == 1:
            return k
    return None

assert is_prime(n)
phi = n - 1
primes = prime_factors(phi)

generator = None
for g in range(2, n):
    if order_mod(g, n, phi) == phi:
        generator = g
        break

if generator is None:
    result = {"final_answer": "UNSUPPORTED", "evidence": {"reason": "no generator found"}}
else:
    unit_count = sum(1 for a in range(1, n) if __import__("math").gcd(a, n) == 1)
    gen_powers = {pow(generator, k, n) for k in range(phi)}
    result = {
        "final_answer": str(generator),
